def transform(grid):
    h, w = len(grid), len(grid[0])
    stripe = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c-r
                if d in stripe and stripe[d] != value:
                    raise ValueError('inconsistent diagonal')
                stripe[d] = value
    period = len(stripe)
    by_residue = {}
    for d, value in stripe.items():
        k=d%period
        if k in by_residue and by_residue[k] != value:
            raise ValueError('inconsistent period')
        by_residue[k]=value
    if len(by_residue) != period:
        raise ValueError('incomplete cycle')
    return [[by_residue[(c-r)%period] for c in range(w)] for r in range(h)]

